SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции1990.Year, Станции1990.NUST, Станции1990.nr, Станции1990.E, Станции1990.EOTP, Станции1990.EURT, Станции1990.EUST, Станции1990.Q, Станции1990.TURT, Станции1990.TUST, Станции1990.B, Станции1990.GAZ, Доп_угли1990.gaz_prir, Доп_угли1990.gazpp, Станции1990.MAZUT, Доп_угли1990.maztop, Доп_угли1990.nft_proch, Доп_угли1990.disel, Станции1990.TORF, Станции1990.SLAN, Станции1990.ISK_GAZ, Доп_угли1990.domen_g, Доп_угли1990.koks_g, Доп_угли1990.prochgaz, Станции1990.PROCH, Доп_угли1990.tvproch, Доп_угли1990.szh_gaz, Доп_угли1990.inoe, Станции1990.UGOL, Станции1990.DON, Станции1990.PODM, Станции1990.PECH, Доп_угли1990.intin, Доп_угли1990.vork, Станции1990.ARKT, Станции1990.KUZN, Доп_угли1990.kuzngd, Доп_угли1990.kuznt, Доп_угли1990.kuznss, Доп_угли1990.kuznun, Станции1990.URAL, Доп_угли1990.sver, Доп_угли1990.chel, Доп_угли1990.kizel, Станции1990.BASHK, Станции1990.KAN, Доп_угли1990.nazar, Доп_угли1990.ibor, Доп_угли1990.berez, Доп_угли1990.per, Доп_угли1990.irbei, Доп_угли1990.kansk, Станции1990.TUNG, Доп_угли1990.jer, Доп_угли1990.karab, Станции1990.IRKUT, Доп_угли1990.azey, Доп_угли1990.mug, Доп_угли1990.cher, Станции1990.HAK, Станции1990.TUV, Станции1990.BUR, Доп_угли1990.gusin, Доп_угли1990.tugn, Доп_угли1990.okino, Станции1990.CHIT, Доп_угли1990.har, Доп_угли1990.urt, Доп_угли1990.tataur, Доп_угли1990.tarbag, Доп_угли1990.zab_kam, Станции1990.YAKUT, Доп_угли1990.neru, Доп_угли1990.zyryan, Доп_угли1990.pyak, Станции1990.AMUR, Доп_угли1990.rai, Доп_угли1990.erk, Доп_угли1990.ogodj, Станции1990.URG, Станции1990.USHUM, Станции1990.PRIM, Доп_угли1990.bikin, Доп_угли1990.razdol, Доп_угли1990.hankai, Станции1990.MAG, Станции1990.SAH, Станции1990.KAMCH, Станции1990.CHUKOT, Доп_угли1990.anad, Доп_угли1990.bering, Станции1990.KAZAH, Доп_угли1990.ekib, Доп_угли1990.maikub, Доп_угли1990.karag, Доп_угли1990.karajyra, Доп_угли1990.teniz, Станции1990.QOTR, Станции1990.SNK, Станции1990.EWTP, Станции1990.NT, Станции1990.OBOR, Станции1990.VED, Станции1990.OBL, Станции1990.DEP, Станции1990.OES, Станции1990.ER, Станции1990.NUMB1120, Имена_станций.Ведомство AS вед, IIf([вед]=1 Or [вед]=4,1,IIf([вед]=2 Or [вед]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Имена_станций.BE, имена_ГК.name AS namegk, [Филиалы ГК].name AS filial, IIf([OBOR]=20 Or [OBOR]=90,"ГТУ",IIf([OBOR]=21 Or [OBOR]=91,"ПГУ",IIf([OBOR]=22,"Диз",IIf([OBOR]=23,"ГУБТ",IIf([OBOR]=24 Or [OBOR]=89,"ГПА","ПСУ"))))) AS тип, Станции1990.SNt, Имена_станций.n1 AS [мощность блока], IIf([B]>0,[gaz_prir]/[B]*100,0) AS dolya_gaz_prir, IIf([B]>0,[gazpp]/[B]*100,0) AS dolya_gazpp, IIf([B]>0,[UGOL]/[B]*100,0) AS dolya_ugol, IIf([B]>0,[MAZUT]/[B]*100,0) AS dolya_mazut, IIf([B]>0,[TORF]/[B]*100,0) AS dolya_torf, IIf([B]>0,[SLAN]/[B]*100,0) AS dolya_slan, IIf([B]>0,[PROCH]/[B]*100,0) AS dolya_proch, IIf([E]>0,[EWTP]/[E]*100,0) AS dolya_ewtp, IIf([Q]>0,[QOTR]/[Q]*100,0) AS dolya_qotr, IIf([B]>0 And [domen_g]>0,[domen_g]/[B]*100,0) AS dolya_domen_g, IIf([B]>0 And [koks_g]>0,[koks_g]/[B]*100,0) AS dolya_koks_g, IIf([B]>0 And [prochgaz]>0,[prochgaz]/[B]*100,0) AS dolya_prochgaz, IIf([B]>0,IIf([dolya_gaz_prir]>=50,"gaz_prir",IIf([dolya_gazpp]>=50,"gazpp",IIf([dolya_domen_g]>=50,"domen_g",IIf([dolya_koks_g]>=50,"koks_g",IIf([dolya_prochgaz]>=50,"prochgaz",IIf([dolya_ugol]>=50,"ugol",IIf([dolya_mazut]>=50,"neftetopl","prochee"))))))),"net topliva") AS nov_Belyaev, Имена_областей.Terr_Belyaev, IIf([E]>0,([E]-[EOTP])/[E]*100,0) AS [%_sn], IIf([Имена_станций.BE]=9,"Пром.предпр.","Минэнерго") AS BLST_BE, IIf([Ведомство]=1,"Минэнерго","Пром.предпр.") AS BLST_V, IIf([вед]=1,"Минэнерго","Пром.предпр.") AS BLST_ved, Типы_оборудования.gruppa_oborud
FROM (((Имена_станций INNER JOIN (Имена_областей RIGHT JOIN (Имена_ОЭС INNER JOIN (Станции1990 LEFT JOIN Доп_угли1990 ON (Станции1990.NUMB1120 = Доп_угли1990.NUMB1120) AND (Станции1990.YEAR = Доп_угли1990.YEAR)) ON Имена_ОЭС.oes = Станции1990.OES) ON Имена_областей.OBL = Станции1990.OBL) ON Имена_станций.NUMB = Станции1990.NUMB1120) LEFT JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) LEFT JOIN [Филиалы ГК] ON Имена_станций.GKF = [Филиалы ГК].code) INNER JOIN Типы_оборудования ON Станции1990.OBOR = Типы_оборудования.code;
